import{_ as t,o as a,c as o,a6 as r}from"./chunks/framework.DIp0zHSV.js";const p=JSON.parse('{"title":"Core Subsystems","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/subsystems/index.md","filePath":"architecture/subsystems/index.md","lastUpdated":1794269686000}'),d={name:"architecture/subsystems/index.md"};function n(s,e,c,i,l,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="core-subsystems" tabindex="-1">Core Subsystems <a class="header-anchor" href="#core-subsystems" aria-label="Permalink to &quot;Core Subsystems&quot;">​</a></h1><p>LCARdS exposes a set of singleton services on <code>window.lcards.core.*</code>. <code>window.lcards.core</code> is the <code>LCARdSCore</code> instance itself (<code>src/lcards-main.js</code> assigns <code>window.lcards.core = lcardsCore</code>), so every service below is a property of that object, created once by <code>LCARdSCore._performInitialization()</code> (<code>src/core/lcards-core.js</code>). Cards never instantiate core subsystems themselves; they read them from <code>window.lcards.core</code> (or from the <code>_singletons</code> map <code>LCARdSCard</code> builds from it).</p><p>Fourteen services extend <code>BaseService</code> (<code>src/core/BaseService.js</code>): <code>themeManager</code>, <code>rulesManager</code>, <code>dataSourceManager</code>, <code>animationManager</code>, <code>assetManager</code>, <code>helperManager</code>, <code>soundManager</code>, <code>screenEffectManager</code>, <code>borgAssimilationManager</code>, <code>integrationService</code>, <code>deviceIdentityManager</code>, <code>scopedSettingsService</code>, <code>portalOverlayManager</code> and <code>connectionOverlayService</code>. The rest are plain classes: <code>systemsManager</code> (<code>CoreSystemsManager</code>), <code>validationService</code>, <code>configManager</code>, <code>stylePresetManager</code>, <code>componentManager</code>, <code>packManager</code> and <code>performanceMonitor</code>. Being a <code>BaseService</code> only gives a class no-op <code>updateHass()</code> / <code>ingestHass()</code> defaults and <code>getServiceInfo()</code>; whether a service actually receives HASS is decided by the list in <code>LCARdSCore._updateHass()</code> (see <a href="#hass-distribution">HASS distribution</a>).</p><p>To inspect any of them from the browser console, use <code>window.lcards.debug.singleton(&#39;&lt;name&gt;&#39;)</code> (it calls that service&#39;s <code>getDebugInfo()</code>) and <code>window.lcards.debug.singletons()</code> (every service that has one). See <a href="./../../development/debug-api.html#debug-singleton-manager">Debug API: <code>debug.singleton(manager)</code></a>.</p><hr><h2 id="quick-reference" tabindex="-1">Quick Reference <a class="header-anchor" href="#quick-reference" aria-label="Permalink to &quot;Quick Reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Subsystem</th><th>Singleton</th><th>Class (file under <code>src/</code>)</th><th>Role</th></tr></thead><tbody><tr><td><a href="#animation-manager">Animation Manager</a></td><td><code>animationManager</code></td><td><code>AnimationManager</code> (<code>core/animation/AnimationManager.js</code>)</td><td>anime.js v4 orchestration, scoped per overlay</td></tr><tr><td><a href="#asset-manager">Asset Manager</a></td><td><code>assetManager</code></td><td><code>AssetManager</code> (<code>core/assets/AssetManager.js</code>)</td><td>SVG / font / audio / image loading and caching</td></tr><tr><td><a href="#borg-assimilation">Borg Assimilation</a></td><td><code>borgAssimilationManager</code></td><td><code>BorgAssimilationManager</code> (<code>core/borg/BorgAssimilationManager.js</code>)</td><td>The assimilate / deassimilate screen takeover</td></tr><tr><td><a href="#component-manager">Component Manager</a></td><td><code>componentManager</code></td><td><code>ComponentManager</code> (<code>core/components/ComponentManager.js</code>)</td><td>Named multi-segment SVG component registry</td></tr><tr><td><a href="#config-manager">Config Manager</a></td><td><code>configManager</code></td><td><code>CoreConfigManager</code> (<code>core/config-manager/index.js</code>)</td><td>Card config merge pipeline with provenance</td></tr><tr><td><a href="#connection-overlay">Connection Overlay</a></td><td><code>connectionOverlayService</code></td><td><code>ConnectionOverlayService</code> (<code>core/services/ConnectionOverlayService.js</code>)</td><td>Full-screen lost-connection UI</td></tr><tr><td><a href="#datasource-system">DataSource System</a></td><td><code>dataSourceManager</code></td><td><code>DataSourceManager</code> (<code>core/data-sources/DataSourceManager.js</code>)</td><td>Named entity buffers with processor pipelines</td></tr><tr><td><a href="#device-identity">Device Identity</a></td><td><code>deviceIdentityManager</code></td><td><code>DeviceIdentityManager</code> (<code>core/services/DeviceIdentityManager.js</code>)</td><td>Stable per-browser UUID and display name</td></tr><tr><td><a href="#helper-manager">Helper Manager</a></td><td><code>helperManager</code></td><td><code>LCARdSHelperManager</code> (<code>core/helpers/lcards-helper-manager.js</code>)</td><td>LCARdS <code>input_*</code> helper entities: create, read, write, watch</td></tr><tr><td><a href="#integration-service">Integration Service</a></td><td><code>integrationService</code></td><td><code>IntegrationService</code> (<code>core/services/IntegrationService.js</code>)</td><td>Backend probe, global storage helpers, push events</td></tr><tr><td><a href="#pack-system">Pack System</a></td><td><code>packManager</code></td><td><code>PackManager</code> (<code>core/PackManager.js</code>)</td><td>Loads built-in packs into the registries</td></tr><tr><td><a href="#performance-monitor">Performance Monitor</a></td><td><code>performanceMonitor</code></td><td><code>AnimationPerformanceMonitor</code> (<code>core/animation/PerformanceMonitor.js</code>)</td><td>FPS watch for canvas background animations</td></tr><tr><td><a href="#portal-overlay-manager">Portal Overlay Manager</a></td><td><code>portalOverlayManager</code></td><td><code>PortalOverlayManager</code> (<code>core/services/PortalOverlayManager.js</code>)</td><td>Named full-screen overlay slots in the effect portal</td></tr><tr><td><a href="#rules-engine">Rules Engine</a></td><td><code>rulesManager</code></td><td><code>RulesEngine</code> (<code>core/rules/RulesEngine.js</code>)</td><td>Condition evaluation, style patches on overlays</td></tr><tr><td><a href="#scoped-settings">Scoped Settings</a></td><td><code>scopedSettingsService</code></td><td><code>ScopedSettingsService</code> (<code>core/services/ScopedSettingsService.js</code>)</td><td>Device, user, global settings waterfall</td></tr><tr><td><a href="#screen-effect-system">Screen Effect System</a></td><td><code>screenEffectManager</code></td><td><code>ScreenEffectManager</code> (<code>core/screen-effects/ScreenEffectManager.js</code>)</td><td>Full-screen composited effect layers</td></tr><tr><td><a href="#sound-system">Sound System</a></td><td><code>soundManager</code></td><td><code>SoundManager</code> (<code>core/sound/SoundManager.js</code>)</td><td>Event-driven audio with scheme mapping</td></tr><tr><td><a href="#style-preset-manager">Style Preset Manager</a></td><td><code>stylePresetManager</code></td><td><code>StylePresetManager</code> (<code>core/presets/StylePresetManager.js</code>)</td><td>Named preset bundles loaded from packs</td></tr><tr><td><a href="#systems-manager">Systems Manager</a></td><td><code>systemsManager</code></td><td><code>CoreSystemsManager</code> (<code>core/systems-manager/index.js</code>)</td><td>Entity state cache, subscriptions, overlay registry</td></tr><tr><td><a href="#template-system">Template System</a></td><td><em>(no singleton: instantiated per use)</em></td><td><code>UnifiedTemplateEvaluator</code> (<code>core/templates/UnifiedTemplateEvaluator.js</code>)</td><td>Evaluator for all four template types</td></tr><tr><td><a href="#theme-system">Theme System</a></td><td><code>themeManager</code></td><td><code>ThemeManager</code> (<code>core/themes/ThemeManager.js</code>)</td><td>Token resolution, alert palette transforms</td></tr><tr><td><a href="#validation-service">Validation Service</a></td><td><code>validationService</code></td><td><code>CoreValidationService</code> (<code>core/validation-service/index.js</code>)</td><td>Runtime config schema validation by card type</td></tr></tbody></table><hr><h2 id="initialization-order" tabindex="-1">Initialization Order <a class="header-anchor" href="#initialization-order" aria-label="Permalink to &quot;Initialization Order&quot;">​</a></h2><p><code>src/lcards-main.js</code> calls <code>lcardsCore.initialize(stubHass)</code> when the bundle loads, with a stub HASS (<code>states: {}</code>, no <code>connection</code>, <code>user.is_admin: false</code>). <code>initialize()</code> runs <code>_performInitialization()</code> once; a second caller that arrives while it runs waits for it and then applies its own (real) HASS through <code>_updateHass()</code>. Cards that call <code>registerCard()</code> before the core is ready are queued in <code>_pendingCards</code>.</p><p><code>_performInitialization(hass)</code> (<code>src/core/lcards-core.js</code>) runs these steps in order. &quot;Created&quot; means the constructor only; &quot;initialized&quot; means an <code>initialize()</code> call is awaited.</p><table tabindex="0"><thead><tr><th>#</th><th>Step</th><th>Notes</th></tr></thead><tbody><tr><td>1</td><td><code>injectPalette()</code></td><td>Writes the LCARdS palette as <code>--lcards-*</code> CSS variables, before any theme exists</td></tr><tr><td>2</td><td><code>systemsManager</code> created, <code>initialize(hass)</code></td><td>Entity cache and overlay registry</td></tr><tr><td>3</td><td><code>dataSourceManager</code> created with <code>hass</code></td><td>Sources are created later by cards (<code>createDataSource()</code>) or MSD (<code>initializeFromConfig()</code>)</td></tr><tr><td>4</td><td><code>rulesManager</code> created</td><td><code>rulesManager.systemsManager</code> is set so rules can reach the overlay registry</td></tr><tr><td>5</td><td><code>themeManager</code> created</td><td>Themes arrive with the packs in step 15</td></tr><tr><td>6</td><td><code>animationManager</code> created with <code>systemsManager</code>, <code>initialize([], { suppressMountWarning: true })</code></td><td></td></tr><tr><td>7</td><td><code>performanceMonitor</code> created</td><td>Starts measuring only when a canvas background calls <code>start()</code></td></tr><tr><td>8</td><td><code>validationService</code> created, <code>initialize(hass)</code></td><td></td></tr><tr><td>9</td><td><code>configManager</code> created, <code>initialize({ validationService })</code></td><td>Early, because cards process config from the moment they exist; theme and preset managers are added in step 17</td></tr><tr><td>10</td><td><code>stylePresetManager</code> created</td><td>Presets arrive with the packs</td></tr><tr><td>11</td><td><code>assetManager</code> created, <code>initialize()</code></td><td></td></tr><tr><td>12</td><td><code>componentManager</code> created, <code>initialize()</code></td><td></td></tr><tr><td>13</td><td><code>helperManager</code> created with <code>hass</code></td><td></td></tr><tr><td>14</td><td><code>soundManager</code> created, <code>initialize(core)</code></td><td></td></tr><tr><td>15</td><td><code>packManager</code> created, <code>loadBuiltinPacks()</code></td><td>The only place built-in packs are loaded; fills themes, presets, components, assets, sound schemes</td></tr><tr><td>16</td><td>Fonts with <code>metadata.autoLoad</code> loaded</td><td>Fire-and-forget <code>assetManager.loadFont(key)</code></td></tr><tr><td>17</td><td><code>themeManager.activateTheme(&#39;lcards-default&#39;)</code>, then <code>configManager.updateContext({ themeManager, stylePresetManager })</code></td><td>A failed theme activation is logged, not fatal</td></tr><tr><td>18</td><td>Debug APIs attached</td><td><code>window.lcards.debug.datasources</code>, and <code>debug.core</code> / <code>debug.singleton</code> / <code>debug.singletons</code> from <code>CoreDebugAPI</code></td></tr><tr><td>19</td><td><code>screenEffectManager</code> created</td><td>The portal is appended to <code>document.body</code> on first use</td></tr><tr><td>20</td><td><code>borgAssimilationManager</code> created</td><td>Needs the screen effect and theme managers</td></tr><tr><td>21</td><td><code>integrationService</code> created</td><td>Probes <code>lcards/info</code> on the first HASS that has a <code>connection</code></td></tr><tr><td>22</td><td><code>deviceIdentityManager</code> created</td><td>Initialises on its first <code>updateHass()</code></td></tr><tr><td>23</td><td><code>scopedSettingsService</code> created</td><td></td></tr><tr><td>24</td><td><code>portalOverlayManager</code> created</td><td></td></tr><tr><td>25</td><td><code>connectionOverlayService</code> created, <code>updateHass(hass)</code></td><td>Subscribes to connection events as soon as it sees a HASS with a <code>connection</code> (the module-load stub has none, so in practice on the first real HASS)</td></tr><tr><td>26</td><td>Two <code>integrationService.onReady()</code> follow-ups registered</td><td><code>themeManager.loadOverrides()</code> and <code>connectionOverlayService.initialize()</code>, both fire-and-forget</td></tr><tr><td>27</td><td><code>_coreInitialized = true</code>, <code>_startGlobalHassFeed()</code></td><td>See <a href="#hass-distribution">HASS distribution</a></td></tr><tr><td>28</td><td><code>soundManager.mountGlobalUIListener()</code>, <code>soundManager.subscribeToAlertMode()</code></td><td></td></tr><tr><td>29</td><td>Queued cards registered</td><td>Each pending <code>registerCard()</code> promise resolves with its card context</td></tr><tr><td>30</td><td><code>system_ready</code> sound</td><td>Once per page load (<code>window._lcardsSystemReadyPlayed</code>), after <code>soundManager.ensureReady()</code></td></tr></tbody></table><p>If any awaited step throws, the core plays the <code>error</code> sound, leaves <code>_coreInitialized</code> false and rethrows.</p><h3 id="hass-distribution" tabindex="-1">HASS distribution <a class="header-anchor" href="#hass-distribution" aria-label="Permalink to &quot;HASS distribution&quot;">​</a></h3><p><code>LCARdSCore._updateHass(hass)</code> pushes a HASS object to these services, in this order, by calling <code>updateHass(hass)</code> on each: <code>systemsManager</code>, <code>dataSourceManager</code>, <code>rulesManager</code>, <code>themeManager</code>, <code>animationManager</code>, <code>validationService</code>, <code>soundManager</code>, <code>integrationService</code>, <code>deviceIdentityManager</code>, <code>scopedSettingsService</code>, <code>portalOverlayManager</code>, <code>connectionOverlayService</code>, <code>assetManager</code>, <code>helperManager</code>. The other services do not receive HASS from the core.</p><p>Three paths lead into it:</p><ul><li><strong>Cards</strong>: <code>LCARdSCard</code> calls <code>window.lcards.core.ingestHass(hass)</code> when a HASS change touches its own entities. <code>ingestHass()</code> keeps only the latest HASS and runs <code>_updateHass()</code> once per microtask, so many cards updating in the same tick cause one distribution.</li><li><strong>Global feed</strong>: <code>_startGlobalHassFeed()</code> polls <code>document.querySelector(&#39;home-assistant&#39;).hass</code> every 500 ms (<code>GLOBAL_HASS_POLL_MS</code>) while no card is registered or a portal overlay shows content, so pages without LCARdS cards (and overlay cards) still get live HASS.</li><li><strong>Direct</strong>: <code>updateHass(hass)</code> on the core calls <code>_updateHass()</code> without the microtask deduplication. Separately, <code>LCARdSNativeCard</code>&#39;s <code>hass</code> setter forwards every real HASS straight to <code>helperManager.ingestHass()</code>, so the alert-mode auto-switch works on any page with a card.</li></ul><hr><h2 id="action-handler" tabindex="-1">Action Handler <a class="header-anchor" href="#action-handler" aria-label="Permalink to &quot;Action Handler&quot;">​</a></h2><p><strong>Per card, not a core singleton</strong> · <a href="./action-handler.html">Full reference →</a></p><p><code>LCARdSActionHandler</code> is created by each card (<code>LCARdSCard</code> constructor: <code>this._actionHandler = new LCARdSActionHandler()</code>); there is no <code>window.lcards.core.actionHandler</code>. It attaches tap, hold, double-tap, hover and leave listeners to card elements, runs the configured Home Assistant action (toggle, more-info, perform-action, navigate, url, assist, plus the astrometrics actions), plays the matching card sound and fires the <code>on_tap</code> / <code>on_hold</code> / <code>on_double_tap</code> / <code>on_hover</code> / <code>on_leave</code> animation triggers with the pointer position.</p><p>Consult this when wiring interactions on a card element or running an action from code.</p><hr><h2 id="animation-manager" tabindex="-1">Animation Manager <a class="header-anchor" href="#animation-manager" aria-label="Permalink to &quot;Animation Manager&quot;">​</a></h2><p><strong><code>window.lcards.core.animationManager</code></strong> · <a href="./animation-manager.html">Full reference →</a></p><p>Orchestrates anime.js v4 animations scoped per overlay. Integrates with DataSource thresholds and the Rules Engine for reactive and rule-triggered playback.</p><p>Consult this when implementing card animations, wiring entity-change or datasource triggers, or using built-in presets like <code>pulse</code> and <code>slide</code>.</p><hr><h2 id="asset-manager" tabindex="-1">Asset Manager <a class="header-anchor" href="#asset-manager" aria-label="Permalink to &quot;Asset Manager&quot;">​</a></h2><p><strong><code>window.lcards.core.assetManager</code></strong> · <a href="./asset-manager.html">Full reference →</a></p><p>Loads and caches SVG, font, and audio assets from packs, keeping a URL-only registry for browser-native image loading. Provides runtime registration of user images as first-class builtin references.</p><p>Consult this when adding custom assets to cards, registering user images, or loading SVG/font content at runtime.</p><hr><h2 id="borg-assimilation" tabindex="-1">Borg Assimilation <a class="header-anchor" href="#borg-assimilation" aria-label="Permalink to &quot;Borg Assimilation&quot;">​</a></h2><p><strong><code>window.lcards.core.borgAssimilationManager</code></strong> · <a href="./borg-assimilation.html">Full reference →</a></p><p>Runs the Borg assimilation sequence: the <code>borg_alert</code> palette, the font swap, the <code>borg-assimilation</code> canvas intro and persistent screen effects, and the deassimilation outro that reverts them. Driven by the <code>lcards.borg_assimilate</code> / <code>lcards.borg_deassimilate</code> actions (through the integration push channel) and the <code>window.lcards.borg.*</code> console API.</p><p>Consult this when changing the assimilation sequence or its defaults.</p><hr><h2 id="component-manager" tabindex="-1">Component Manager <a class="header-anchor" href="#component-manager" aria-label="Permalink to &quot;Component Manager&quot;">​</a></h2><p><strong><code>window.lcards.core.componentManager</code></strong> · <a href="./component-manager.html">Full reference →</a></p><p>Holds named SVG component definitions (dpad, alert, elbow variants) where each segment can receive independent styling and actions. Consumed by button cards running in component mode.</p><p>Consult this when building multi-segment interactive shapes or defining new component types.</p><hr><h2 id="config-manager" tabindex="-1">Config Manager <a class="header-anchor" href="#config-manager" aria-label="Permalink to &quot;Config Manager&quot;">​</a></h2><p><strong><code>window.lcards.core.configManager</code></strong> · <a href="./config-manager.html">Full reference →</a></p><p><code>CoreConfigManager</code> merges a card&#39;s config in layers (behavioural card defaults, theme defaults, preset or component, user config) with provenance tracking, using the validation service, theme manager and style preset manager. Card schemas are registered here for validation.</p><p>Consult this when changing how card config is merged or validated, or when registering a card schema.</p><hr><h2 id="connection-overlay" tabindex="-1">Connection Overlay <a class="header-anchor" href="#connection-overlay" aria-label="Permalink to &quot;Connection Overlay&quot;">​</a></h2><p><strong><code>window.lcards.core.connectionOverlayService</code></strong> · <a href="./connection-overlay.html">Full reference →</a></p><p>Monitors the Home Assistant WebSocket connection and shows a full-screen overlay when the frontend loses server contact. Supports text or custom card modes and optional reconnection banners, configured through the scoped settings waterfall. The overlay is shown in the <code>connection-overlay</code> slot of the Portal Overlay Manager.</p><p>Consult this when customising connection-lost behaviour.</p><hr><h2 id="datasource-system" tabindex="-1">DataSource System <a class="header-anchor" href="#datasource-system" aria-label="Permalink to &quot;DataSource System&quot;">​</a></h2><p><strong><code>window.lcards.core.dataSourceManager</code></strong> · <a href="./datasource-system.html">Full reference →</a></p><p>Manages named data sources: each follows one entity (or attribute), keeps a rolling history buffer and runs a named processor pipeline (unit conversion, smoothing, rate, statistics, ...). Subscribers receive the value and every processor output on each update.</p><p>Consult this when cards need derived sensor data, statistics-based displays, or datasource-driven animations.</p><hr><h2 id="device-identity" tabindex="-1">Device Identity <a class="header-anchor" href="#device-identity" aria-label="Permalink to &quot;Device Identity&quot;">​</a></h2><p><strong><code>window.lcards.core.deviceIdentityManager</code></strong> · <a href="./device-identity.html">Full reference →</a></p><p>Provides a stable browser-profile identity: a UUID kept in <code>localStorage</code> and a display name stored in the backend. This identity is the key for device-scoped settings in the Scoped Settings waterfall and for device targeting of LCARdS actions.</p><p>Consult this when implementing per-device configuration or device-specific features like kiosk overrides.</p><hr><h2 id="helper-manager" tabindex="-1">Helper Manager <a class="header-anchor" href="#helper-manager" aria-label="Permalink to &quot;Helper Manager&quot;">​</a></h2><p><strong><code>window.lcards.core.helperManager</code></strong> · <a href="./helper-manager.html">Full reference →</a></p><p>Manages the Home Assistant helper entities LCARdS uses for shared state (<code>input_select</code>, <code>input_boolean</code>, <code>input_number</code>, <code>input_text</code>): alert mode, alert colour tuning, sound settings and HA-LCARS theme values. Provides typed read/write access, change subscriptions, creation of missing helpers, and the alert-mode auto-switch that applies a changed <code>input_select.lcards_alert_mode</code> to the theme.</p><p>Consult this when implementing features backed by Home Assistant helpers or when reading/writing alert and sound configuration.</p><hr><h2 id="integration-service" tabindex="-1">Integration Service <a class="header-anchor" href="#integration-service" aria-label="Permalink to &quot;Integration Service&quot;">​</a></h2><p><strong><code>window.lcards.core.integrationService</code></strong> · <a href="./integration-service.html">Full reference →</a></p><p>Probes the LCARdS integration (<code>lcards/info</code>) to learn whether the backend is available, wraps the global storage commands (writes are admin-only), and handles push events from the Python actions (reload, log level, alert mode, effects, portal cards, Borg, astrometrics).</p><p>Consult this when implementing backend-dependent features, checking integration availability before persisting data, or handling remote-control directives.</p><hr><h2 id="pack-system" tabindex="-1">Pack System <a class="header-anchor" href="#pack-system" aria-label="Permalink to &quot;Pack System&quot;">​</a></h2><p><strong><code>window.lcards.core.packManager</code></strong> · <a href="./pack-system.html">Full reference →</a></p><p>Defines the structure, loading, and distribution of named bundles containing style presets, components, themes, rules, animations, and assets. Packs are loaded at startup by <code>PackManager</code>; downstream registries consume the declared entries.</p><p>Consult this when creating new packs, adding component types, or understanding how registries populate from pack data.</p><hr><h2 id="performance-monitor" tabindex="-1">Performance Monitor <a class="header-anchor" href="#performance-monitor" aria-label="Permalink to &quot;Performance Monitor&quot;">​</a></h2><p><strong><code>window.lcards.core.performanceMonitor</code></strong> · No page of its own; see <a href="./animation-manager.html">Animation Manager</a></p><p><code>AnimationPerformanceMonitor</code> measures frames per second while at least one <code>Canvas2DRenderer</code> (canvas background animations) has called <code>start()</code> (reference counted; <code>stop()</code> ends the loop when the last one leaves). Readings in the first 5 s after a renderer joins are ignored. Each check dispatches a <code>lcards:performance-check</code> window event with <code>fps</code>, <code>shouldReduceEffects</code> (below <code>reduceEffects</code>, 24 fps) and <code>shouldDisable3D</code> (three consecutive checks below <code>disable3D</code>, 12 fps); <code>Canvas2DRenderer._onPerfCheck()</code> then skips frames or stops. Console access: <code>window.lcards.debug.perf</code> (<code>fps()</code>, <code>status()</code>, <code>thresholds</code>; see <a href="./../../development/debug-api.html#perf-performance-monitor">Debug API: <code>perf</code></a>).</p><hr><h2 id="portal-overlay-manager" tabindex="-1">Portal Overlay Manager <a class="header-anchor" href="#portal-overlay-manager" aria-label="Permalink to &quot;Portal Overlay Manager&quot;">​</a></h2><p><strong><code>window.lcards.core.portalOverlayManager</code></strong> · <a href="./portal-overlay-manager.html">Full reference →</a></p><p>Manages named overlay slots inside the Screen Effect Manager&#39;s fixed portal: <code>alert-overlay</code> (the alert overlay card), <code>connection-overlay</code> (the Connection Overlay) and <code>ha-service</code> (the <code>lcards.show_portal_card</code> action). Each slot mounts a card or a text message, owns its dismiss and duration handling and may claim the screen effect layers; the manager pushes HASS to every mounted card.</p><p>Consult this when showing content above the whole dashboard.</p><hr><h2 id="rules-engine" tabindex="-1">Rules Engine <a class="header-anchor" href="#rules-engine" aria-label="Permalink to &quot;Rules Engine&quot;">​</a></h2><p><strong><code>window.lcards.core.rulesManager</code></strong> · <a href="./rules-engine.html">Full reference →</a></p><p>Evaluates rule conditions on HASS updates and produces style patches that are merged onto target overlays; overlays have no knowledge that a rule is driving them. Supports multi-condition logic and cross-card overlay targeting by tag, type, ID, or pattern.</p><p>Consult this when implementing conditional styling, state-dependent animations, or coordinated alert patterns across multiple cards.</p><hr><h2 id="scoped-settings" tabindex="-1">Scoped Settings <a class="header-anchor" href="#scoped-settings" aria-label="Permalink to &quot;Scoped Settings&quot;">​</a></h2><p><strong><code>window.lcards.core.scopedSettingsService</code></strong> · <a href="./scoped-settings.html">Full reference →</a></p><p>Implements a waterfall (device, then user, then global, then a caller fallback) for LCARdS settings stored in the integration backend. Reads return the most specific value set; writes target one scope. Global writes need a Home Assistant admin.</p><p>Consult this when adding new settings that need per-device or per-user overrides.</p><hr><h2 id="screen-effect-system" tabindex="-1">Screen Effect System <a class="header-anchor" href="#screen-effect-system" aria-label="Permalink to &quot;Screen Effect System&quot;">​</a></h2><p><strong><code>window.lcards.core.screenEffectManager</code></strong> · <a href="./screen-effects.html">Full reference →</a></p><p>Composites full-screen effect layers (backdrop, colour and canvas slots) above the dashboard. Ships named presets (blur, static, pixelate, glitch, vignette and more) used from the console API, the <code>lcards.trigger_effect</code> action and card config. Its fixed portal also hosts the Portal Overlay Manager&#39;s slots, so the connection overlay and alert overlay content sits on top of the effect slots.</p><p>Consult this when implementing visual feedback, alert backdrop effects, or custom canvas-based screen effects.</p><hr><h2 id="sound-system" tabindex="-1">Sound System <a class="header-anchor" href="#sound-system" aria-label="Permalink to &quot;Sound System&quot;">​</a></h2><p><strong><code>window.lcards.core.soundManager</code></strong> · <a href="./sound-system.html">Full reference →</a></p><p>Event-driven audio feedback for card interactions and Home Assistant UI events. Maps events to assets via schemes defined in packs, with per-event overrides and scoped settings support for per-user and per-device sound preferences.</p><p>Consult this when playing sounds on card actions, configuring sound schemes via packs, or implementing per-user/device audio preferences.</p><hr><h2 id="style-preset-manager" tabindex="-1">Style Preset Manager <a class="header-anchor" href="#style-preset-manager" aria-label="Permalink to &quot;Style Preset Manager&quot;">​</a></h2><p><strong><code>window.lcards.core.stylePresetManager</code></strong> · <a href="./style-preset-manager.html">Full reference →</a></p><p>Stores named preset objects (lozenge, bullet, pills, gauge, etc.) loaded from packs. Cards reference presets by name to avoid hard-coding style definitions, and the manager resolves the full preset object at render time.</p><p>Consult this when creating card style presets or when cards need to look up and apply style bundles by name.</p><hr><h2 id="systems-manager" tabindex="-1">Systems Manager <a class="header-anchor" href="#systems-manager" aria-label="Permalink to &quot;Systems Manager&quot;">​</a></h2><p><strong><code>window.lcards.core.systemsManager</code></strong> · <a href="./systems-manager.html">Full reference →</a></p><p>Provides the shared entity state cache with targeted subscriptions and change deduplication for all LCARdS cards, plus an overlay registry used by the Rules Engine for cross-card targeting.</p><p>Consult this when cards need entity state subscriptions, when registering overlays for rule targeting, or performing overlay-aware operations.</p><hr><h2 id="template-system" tabindex="-1">Template System <a class="header-anchor" href="#template-system" aria-label="Permalink to &quot;Template System&quot;">​</a></h2><p><strong><code>new UnifiedTemplateEvaluator(...)</code></strong>: not a core singleton; cards instantiate one directly · <a href="./template-system.html">Full reference →</a></p><p>Unified evaluator for all four LCARdS template types (JavaScript <code>[[[...]]]</code>, LCARdS tokens <code>{...}</code>, DataSource references <code>{ds:...}</code>, and Jinja2 <code>{{...}}</code>) applied in a fixed priority order via <code>UnifiedTemplateEvaluator</code>.</p><p>Consult this when implementing dynamic text fields, understanding template evaluation order, or injecting custom context into expressions.</p><hr><h2 id="theme-system" tabindex="-1">Theme System <a class="header-anchor" href="#theme-system" aria-label="Permalink to &quot;Theme System&quot;">​</a></h2><p><strong><code>window.lcards.core.themeManager</code></strong> · <a href="./theme-system.html">Full reference →</a></p><p>Token-based theming with alert-mode palette transformations. Maintains the active theme registry and resolves <code>theme:</code> token paths to concrete CSS values. The resolver (<code>themeManager.resolver</code>) must be accessed via <code>window.lcards.core</code>; module-level imports have no token tree.</p><p>Consult this when implementing theme-aware styling, accessing theme tokens in code or config, or supporting alert-triggered palette swaps.</p><hr><h2 id="validation-service" tabindex="-1">Validation Service <a class="header-anchor" href="#validation-service" aria-label="Permalink to &quot;Validation Service&quot;">​</a></h2><p><strong><code>window.lcards.core.validationService</code></strong> · <a href="./validation-service.html">Full reference →</a></p><p>Runtime config schema validation keyed by card type. Catches structural errors and unknown fields before render and surfaces them in the editor. Card schemas are registered in <code>CoreConfigManager</code>.</p><p>Consult this when implementing card config validation, understanding error reporting paths, or debugging configuration issues in the editor.</p>',131)])])}const m=t(d,[["render",n]]);export{p as __pageData,m as default};
